//! ♻️ Genuine normal-library context owns staged backing and separate paid header closure.
use semio_framework_job_payload::*;
use semio_framework_trace::{OperationId,Generation};
use semio_framework_value_control_contract::RetainedWorkPoll;
use semio_framework_value_testing_effect_bank::{EffectBank,Wallet};
fn stock(row:&serde_json::Value)->RetainedCloneGrant{let p=&row["stock"];RetainedCloneGrant{maximum_items:p["items"].as_u64().unwrap()as usize,maximum_copy_bytes:p["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:p["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:p["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:p["depth"].as_u64().unwrap()as usize}}
#[test]
fn genuine_original_builder_close_retains_staged_page_until_paid_then_separate_header_clear(){
 let row:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let bank=stock(&row);let quantum=RetainedCloneGrant{maximum_items:1,..bank};
 let mut caller=semio_framework_job::OriginalJobFixtureCaller::admit(OperationId(row["operation"].as_u64().unwrap()),Generation(row["generation"].as_u64().unwrap()),bank,||Some(1),u64::MAX,row["stock"]["fuel"].as_u64().unwrap());let mut owner=RetainedPayloadBuilder::new(JobPayloadStream::Fault);
 for _ in 0..row["stock"]["maximumTurns"].as_u64().unwrap(){if owner.is_initialized(){break;}caller.turn(quantum,|cx|{let turn=owner.advance_initialization(cx);semio_framework_job::receive_original_retained_work(cx,turn)?;Ok(())}).unwrap();}assert!(owner.is_initialized());
 for _ in 0..8{if owner.staged_page_len().is_some(){break;}caller.turn(quantum,|cx|{let turn=owner.begin_staged_page_funded(cx);semio_framework_job::receive_original_retained_work(cx,turn)?;Ok(())}).unwrap();}assert!(owner.staged_page_len().is_some());let pointer=owner.staged_backing_identity();assert!(pointer.is_some());assert_eq!(owner.staged_page_remaining(),row["stagedBytes"].as_u64().unwrap()as usize);assert_eq!(serde_json::to_value(owner.staged_page_len()).unwrap(),serde_json::json!(0));
 let mut effects=EffectBank::new(Wallet::new(bank,row["stock"]["fuel"].as_u64().unwrap()));let denied=effects.run_outcome(RetainedCloneGrant{maximum_items:0,..quantum},1,|effect|owner.close_step(effect));let _=effects.take_admitted();assert_eq!(denied.work,u128::from(row["deniedWork"].as_u64().unwrap()));assert_eq!(denied.result.unwrap().progress(),RetainedCloneProgress::default());assert_eq!(owner.staged_backing_identity(),pointer);
 let mut observed=Vec::new();
 for _ in 0..row["stock"]["maximumTurns"].as_u64().unwrap(){if owner.terminal_is_empty(){break;}let demand=owner.retirement_demands().unwrap();let((units,progress),allocated,released)=semio_framework_trace_memory_testing::observe_backing(||caller.turn(quantum,|cx|{let mut units=0;let step=semio_framework_job::close_original_effect_step(cx,demand,|effect|{let turn=owner.close_step(effect);units=turn.work;RetainedWorkPoll::Complete(turn)})?;Ok((units,match step{semio_framework_job::InteractiveJobCloseStep::Pending{progress}|semio_framework_job::InteractiveJobCloseStep::Complete{progress}=>progress,semio_framework_job::InteractiveJobCloseStep::Blocked=>Default::default()}))}).unwrap());assert_eq!((allocated,released),(progress.retained_capacity_bytes,progress.released_bytes));assert_eq!(progress.copied_bytes,row["copyBytes"].as_u64().unwrap()as usize);observed.push(units);}
 assert!(owner.terminal_is_empty());assert_eq!(serde_json::to_value(observed).unwrap(),row["actualCloseWork"]);let cached=effects.run_outcome(Default::default(),1,|effect|owner.close_step(effect));let _=effects.take_admitted();assert_eq!(cached.work,u128::from(row["cachedWork"].as_u64().unwrap()));assert_eq!(cached.result.unwrap().progress(),RetainedCloneProgress::default());drop(owner);caller.retire(bank);
}

#[test]fn actual_authority_quote_tracks_original_ledger_handback_and_cached_empty(){let grant=RetainedCloneGrant{maximum_items:4,maximum_copy_bytes:4096,maximum_capacity_bytes:4096,maximum_release_bytes:4096,maximum_depth:8};let(turn,allocated,released)=semio_framework_trace_memory_testing::observe_backing(||{let mut actual=None;JobPayloadAuthority::admit(OperationId(9811),Generation(1),grant,&mut actual)});let(mut authority,progress)=turn.result.unwrap().unwrap();assert_eq!((allocated,released),(progress.retained_capacity_bytes,0));let quote=authority.retirement_work_demand().unwrap();assert_eq!(quote,u64::from(authority.original().is_some()));let mut effects=EffectBank::new(Wallet::new(grant,4));let(denied,allocated,released)=semio_framework_trace_memory_testing::observe_backing(||{let turn=effects.run_outcome(RetainedCloneGrant{maximum_items:0,..grant},1,|effect|authority.close_step(effect));let _=effects.take_admitted();turn});assert_eq!((allocated,released,denied.work),(0,0,0));assert!(!authority.terminal_is_empty());let(closed,allocated,released)=semio_framework_trace_memory_testing::observe_backing(||{let turn=effects.run_outcome(grant,quote,|effect|authority.close_step(effect));let _=effects.take_admitted();turn});assert_eq!(closed.work,u128::from(quote));let actual=closed.result.unwrap().progress();assert_eq!((allocated,released),(0,actual.released_bytes));assert_eq!(actual.released_bytes,progress.retained_capacity_bytes);assert!(authority.terminal_is_empty());assert_eq!(authority.retirement_work_demand().unwrap(),0);assert_eq!(effects.run_outcome(grant,1,|effect|authority.close_step(effect)).work,0);let _=effects.take_admitted();}
